def loads(value: str, use_rapid_json: bool = False, **kwargs) -> JSONData:
    with sentry_sdk.start_span(op="sentry.utils.json.loads"):
        if use_rapid_json is True:
            return rapidjson.loads(value)
        else:
            return _default_decoder.decode(value)

def timing(
    key: str,
    value: Union[int, float],
    instance: Optional[str] = None,
    tags: Optional[Tags] = None,
    sample_rate: float = settings.SENTRY_METRICS_SAMPLE_RATE,
) -> None:
    current_tags = _get_current_global_tags()
    if tags is not None:
        current_tags.update(tags)

    try:
        backend.timing(key, value, instance, current_tags, sample_rate)
    except Exception:
        logger = logging.getLogger("sentry.errors")
        logger.exception("Unable to record backend metric")
